dtsPropsFor.StatusDot:
/** UI-11: the status axis is always a circle — filled for connected/connecting/failed, outline for disc/unknown. `connecting` adds a pulse ring. */
status: 'connected' | 'connecting' | 'failed' | 'disc' | 'unknown';
/** Diameter in px: 8 = server rows (default), 7 = the tab strip, 6 = tunnel cards. */
size?: 6 | 7 | 8;

dtsPropsFor.GroupHeader:
/** Group name; rendered upper-cased. */
group: string;
/** Servers in the group — stays visible while collapsed. */
count: number;
/** Drives the folder glyph: closed when true, open when false. */
collapsed: boolean;
/** The whole header is the collapse toggle. */
onToggle: () => void;

dtsPropsFor.TagsEditor:
/** The whole ServerForm value object — this editor reads and rewrites `form.tags`. */
form: { name: string; host: string; port: number | ''; user: string; authType: string; keyPath: string; password: string; passphrase: string; totpSecret: string; twoFactor: boolean; group: string; environment: string; tags: string[]; notes: string; jumpId: string | null };
/** Always called with a NEW object (and a new `tags` array) — never mutated in place. */
setForm: (form: TagsEditorProps['form']) => void;

dtsPropsFor.ServerFormGroup:
form: { name: string; host: string; port: number | ''; user: string; authType: string; keyPath: string; password: string; passphrase: string; totpSecret: string; twoFactor: boolean; group: string; environment: string; tags: string[]; notes: string; jumpId: string | null };
setForm: (form: ServerFormGroupProps['form']) => void;
/** Deduped, sorted group names already in use. Picking "+ New group…" swaps the select for a text input. */
groups: string[];

dtsPropsFor.TwoFactorFields:
form: { name: string; host: string; port: number | ''; user: string; authType: string; keyPath: string; password: string; passphrase: string; totpSecret: string; twoFactor: boolean; group: string; environment: string; tags: string[]; notes: string; jumpId: string | null };
setForm: (form: TwoFactorFieldsProps['form']) => void;
/** Editing an existing server — adds the "leave blank to keep the current secret" hint (SEC-01: a stored secret is never read back). */
editing: boolean;

dtsPropsFor.DestFields:
/** Tailwind class string for the two inputs — passed down by the parent form so every field shares one definition. NOT a field name. */
field: string;
/** Tailwind class string for the two labels. NOT the label text. */
label: string;
destHost: string;
setDestHost: (v: string) => void;
/** '' while the box is empty, so a cleared port doesn't become 0. */
destPort: number | '';
setDestPort: (v: number | '') => void;

dtsPropsFor.Row:
label: string;
/** Secondary line under the label. */
hint?: string;
/** The control(s) on the right. */
children: React.ReactNode;
/** Drops the bottom divider on the last row of a section. */
last?: boolean;

dtsPropsFor.Stepper:
value: number;
onChange: (v: number) => void;
min: number;
max: number;
/** Rendered straight after the value, e.g. 'px'. */
suffix?: string;

dtsPropsFor.ContextMenu:
/** Viewport coordinates of the click; clamped so the menu never spills off-screen. */
x: number;
y: number;
items: ({ label: string; run: () => void; danger?: boolean; disabled?: boolean; keepOpen?: boolean } | 'separator')[];
/** Fired by Escape, an outside click, and an outside right-click. */
onClose: () => void;

dtsPropsFor.Select:
/** The selected value (string or number). */
value: string | number;
/** Each option; `adornment` is an optional leading node, e.g. an environment colour square. */
options: { value: string | number; label: string; adornment?: React.ReactNode }[];
onChange: (v: string | number) => void;
/** Accessible name for the trigger button. */
ariaLabel?: string;
/** Start opened (uncontrolled) — used to show the option list in previews. */
defaultOpen?: boolean;

dtsPropsFor.Input:
/** The shared form text input — one definition of the h-30 field style. Accepts all standard <input> attributes. */
value?: string | number;
onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void;
placeholder?: string;
/** Native input type (text default, e.g. 'password'). */
type?: string;
disabled?: boolean;
/** Extra classes merged after the base field style, e.g. 'font-mono'. */
className?: string;
